INSERT INTO `publication_event_submissions` (`id`, `submitted_by`, `email_address`, `title`, `activity_type`, `start_date`, `end_date`, `activity_time`, `venue`, `lead_office`, `partner_offices`, `person_in_charge`, `participant_count`, `background`, `objectives`, `activity_highlights`, `key_outputs`, `impact_significance`, `quotable_statement`, `remembrance_sentence`, `preferred_publication_date`, `privacy_confirmed`, `created_at`, `status`, `publication_notes`, `reviewed_by`, `reviewed_at`, `published_at`, `updated_at`, `public_token`) VALUES
('10', '19', 'fuenteswyralin@yahoo.com', 'Philippine Integrated Management of Acute Malnutrition(PIMAM) Service Provider\'s Training Workshop', 'Training / Seminar', '2026-09-14', '2026-09-15', '', '2nd Floor,NDD Building,ASTMMC', 'OPD-Nutrition Program Committee', 'City Nutrition Office ,BNS of Tandag City', 'Wyralin L. Fuentes', '45', 'This training initiative is aligned with ASTMMC’s mission of enhancing the health and welfare of Caraganons through sustainable, quality healthcare services. It reinforces patient-centered care by equipping healthcare providers with the competencies to deliver responsive, respectful, and individualized care to children and their families, while also emphasizing the critical role of health education and community-based awareness campaigns in addressing acute malnutrition. Through strengthening the knowledge and skills of healthcare providers, the training ensures appropriate clinical management of both uncomplicated and complicated cases, and promotes preventive measures, early detection, and timely care-seeking behaviors at the community level.', '1.	Describe and demonstrate their roles and responsibilities as members of the healthcare team in the management of acute malnutrition among children under five; and\r\n2.	Apply the basic guidelines of the Philippine Integrated Management of Acute Malnutrition (PIMAM) to effectively identify and manage acute malnutrition cases.', '	Develop a comprehensive understanding of acute Malnutrition, its causes, symptoms, and impact on child health and development\r\n\r\n	Determine and understand health care personnels roles and responsibilities as a part of the team in Management of Acute malnutrition children under five.\r\n\r\n	Accurately assess, classify, and manage children with acute malnutrition by differentiating MAM from SAM, performing correct anthropometric measurements and clinical assessments, and applying appropriate admission, treatment, and discharge procedures in Intensive Therapeutic Care in accordance with standard guidelines.\r\n\r\n	Demonstrate competence in the management of acute malnutrition by providing appropriate medical, nutritional, and inpatient/outpatient care for Severe Acute Malnutrition (SAM), effectively managing complications, implementing nutrition rehabilitation protocols, delivering effective caregiver counseling, and utilizing referral and coordination systems to ensure continuity and quality of patient care.', 'Healthcare providers shall work collaboratively as a multidisciplinary team in providing appropriate care for children with acute malnutrition.', 'Strengthens hospital–community coordination\r\nPIMAM-trained providers can establish better coordination between the hospital and LGU nutrition programs, particularly for referral, discharge planning, follow-up, monitoring, and reporting. This is important because successful management of acute malnutrition does not end when the child leaves the hospital.', '1', '', NULL, '1', '2026-09-14 13:50:10', 'In Preparation', '', '15', '2026-09-14 15:23:42', NULL, '2026-09-16 10:45:28', 'e558a402b15770036be3ad398fc927ca19d531acdf53349580a6c42dde2440b3'),
('11', '19', 'fuenteswyralin@yahoo.com', 'Philippine Integrated Management of Acute Malnutrition (PIMAM) Service Provider\'s Training-Workshop', 'Training / Seminar', '2026-09-14', '2026-09-15', '', 'Allied Hall, 2nd floor NDD Building', 'OPD NUTRITION PROGRAM COMMITTEE', 'TANDAG CITY NUTRITION OFFICE, BNS FROM TANDAG', 'WYRALIN FUENTES,RND, MPA', '45', 'This training initiative is aligned with ASTMMC’s mission of enhancing the health and welfare of Caraganons through sustainable, quality healthcare services. It reinforces patient-centered care by equipping healthcare providers with the competencies to deliver responsive, respectful, and individualized care to children and their families, while also emphasizing the critical role of health education and community-based awareness campaigns in addressing acute malnutrition. Through strengthening the knowledge and skills of healthcare providers, the training ensures appropriate clinical management of both uncomplicated and complicated cases, and promotes preventive measures, early detection, and timely care-seeking behaviors at the community level.', '1.	Describe and demonstrate their roles and responsibilities as members of the healthcare team in the management of acute malnutrition among children under five; and\r\n2.	Apply the basic guidelines of the Philippine Integrated Management of Acute Malnutrition (PIMAM) to effectively identify and manage acute malnutrition cases.\r\n\r\nIII. TRAINING DETAILS', '	Develop a comprehensive understanding of acute Malnutrition, its causes, symptoms, and impact on child health and development\r\n\r\n	Determine and understand health care personnels roles and responsibilities as a part of the team in Management of Acute malnutrition children under five.\r\n\r\n	Accurately assess, classify, and manage children with acute malnutrition by differentiating MAM from SAM, performing correct anthropometric measurements and clinical assessments, and applying appropriate admission, treatment, and discharge procedures in Intensive Therapeutic Care in accordance with standard guidelines.\r\n\r\n	Demonstrate competence in the management of acute malnutrition by providing appropriate medical, nutritional, and inpatient/outpatient care for Severe Acute Malnutrition (SAM), effectively managing complications, implementing nutrition rehabilitation protocols, delivering effective caregiver counseling, and utilizing referral and coordination systems to ensure continuity and quality of patient care.', 'Healthcare providers shall work collaboratively as a multidisciplinary team in providing appropriate care for children with acute malnutrition.\r\nParticipants shall strengthen coordination and referral mechanisms between inpatient, outpatient, and community-based services to ensure continuity of care.', 'Strengthens hospital–community coordination\r\nPIMAM-trained providers can establish better coordination between the hospital and LGU nutrition programs, particularly for referral, discharge planning, follow-up, monitoring, and reporting. This is important because successful management of acute malnutrition does not end when the child leaves the hospital.', '', '', NULL, '1', '2026-09-14 13:54:16', 'In Preparation', '', '15', '2026-09-14 15:20:52', NULL, '2026-09-16 16:52:40', '05c70b9d4728788b416a729dd868cc039fc9ba725cc2992b33692fe3cfe43489'),
('12', '13', 'recklynruaza@gmail.com', 'Generic Awareness Month Celebration', 'Others', '2026-09-21', '2026-09-21', '8:00 am - 3:00 PM', 'ASTMMC AVR', 'Pharmacy', NULL, 'Pharmacy', NULL, 'Coordinate with program facilitator', 'Coordinate with program facilitator', 'Coordinate with program facilitator', 'Coordinate with program facilitator', 'Coordinate with program facilitator', NULL, NULL, '2026-09-21', '1', '2026-09-21 15:58:23', 'Closed', '', '13', '2026-09-22 09:33:28', '2026-09-22 09:09:50', '2026-09-22 09:33:28', 'a485783b4bab4f7b719b20ba62708e35a63b6658dc057fd57b831583e6aa98ea');
