('contribution', '6', 'ASAFHHNBKL', 'ASAFHHNBKL---', '[{\"url\": \"https://www.facebook.com/photo/?fbid=1567092705438530&set=pcb.1567093032105164\", \"type\": \"Facebook\"}]', '13', '2026-09-21 17:41:12', '[{\"material\":\"Layout\",\"stored_name\":\"2f4ebae8c254a6c97b08cc680ec35341.jpg\",\"original_name\":\"Congratulations famed.jpg\",\"extension\":\"jpg\",\"size\":8011345,\"mime\":\"image/jpeg\",\"uploaded_by\":10,\"uploader_name\":\"ACE RAZ CABUGA\",\"uploaded_at\":\"2026-09-21 17:34:22\"}]'),
('contribution', '7', 'SGKANGLKNADKLFGHA', 'SGKANGLKNADKLFGHA', '[{\"url\": \"https://www.facebook.com/photo/?fbid=1567076645440136&set=a.693122579502218\", \"type\": \"Facebook\"}]', '13', '2026-09-22 08:51:28', '[{\"material\":\"Layout\",\"stored_name\":\"304d1160190c67e034a18e628d9dcca8.png\",\"original_name\":\"ChatGPT Image Sep 21, 2026, 05_45_22 PM.png\",\"extension\":\"png\",\"drive_url\":\"\",\"size\":1773490,\"mime\":\"image/png\",\"uploaded_by\":10,\"uploader_name\":\"ACE RAZ CABUGA\",\"uploaded_at\":\"2026-09-22 08:31:55\"},{\"material\":\"Video/Reels\",\"stored_name\":\"eeb88d1f669a3c9a58aa75be89699757.mp4\",\"original_name\":\"HOCPR (Drowning).mp4\",\"extension\":\"mp4\",\"drive_url\":\"\",\"size\":347541594,\"mime\":\"video/mp4\",\"uploaded_by\":10,\"uploader_name\":\"ACE RAZ CABUGA\",\"uploaded_at\":\"2026-09-22 08:32:13\"},{\"material\":\"Video/Reels\",\"stored_name\":\"\",\"original_name\":\"Google Drive link\",\"extension\":\"drive\",\"drive_url\":\"https://drive.google.com/drive/u/0/folders/1GGQL_dwL0LY3qVdbdcynJS_tWyO1ogCv\",\"size\":0,\"mime\":\"text/uri-list\",\"uploaded_by\":10,\"uploader_name\":\"ACE RAZ CABUGA\",\"uploaded_at\":\"2026-09-22 08:49:16\"}]'),
('event', '12', '', '𝐆𝐄𝐍𝐄𝐑𝐈𝐂𝐒: 𝐊𝐀𝐓𝐔𝐖𝐀𝐍𝐆 𝐒𝐀 𝐊𝐀𝐋𝐔𝐒𝐔𝐆𝐀𝐍\r\n𝑲𝒏𝒐𝒘𝒊𝒏𝒈 𝒚𝒐𝒖𝒓 𝒎𝒆𝒅𝒊𝒄𝒊𝒏𝒆 𝒉𝒆𝒍𝒑𝒔 𝒚𝒐𝒖 𝒕𝒂𝒌𝒆 𝒂 𝒎𝒐𝒓𝒆 𝒊𝒏𝒇𝒐𝒓𝒎𝒆𝒅 𝒓𝒐𝒍𝒆 𝒊𝒏 𝒚𝒐𝒖𝒓 𝒄𝒂𝒓𝒆.\r\nKnowing what medicine you are taking is an important part of taking an active role in your own health. Understanding its generic name can help you better understand your prescription, ask the right questions, and make informed decisions together with your healthcare provider.\r\nIn observance of 𝐆𝐞𝐧𝐞𝐫𝐢𝐜 𝐀𝐰𝐚𝐫𝐞𝐧𝐞𝐬𝐬 𝐌𝐨𝐧𝐭𝐡 𝟐𝟎𝟐𝟔, Adela Serra Ty Memorial Medical Center (ASTMMC) opened its week-long activities with a symposium for hospital employees, bringing attention to the medicines prescribed to patients—and the names behind them.\r\nCarrying the theme “𝐊𝐚𝐥𝐮𝐬𝐮𝐠𝐚𝐧 𝐧𝐠 𝐁𝐚𝐰𝐚𝐭 𝐏𝐢𝐥𝐢𝐩𝐢𝐧𝐨, 𝐆𝐞𝐧𝐞𝐫𝐢𝐜𝐬 𝐚𝐧𝐠 𝐊𝐚𝐭𝐮𝐰𝐚𝐧𝐠 𝐌𝐨,” the observance runs until September 25, 2026, with activities aimed at strengthening awareness of generic medicines and promoting their safe and responsible use.\r\nBeyond the name on the label, understanding what medicine you are taking, why it is prescribed, and how it should be used can help you become a more informed partner in your own care.\r\nThroughout the week, ASTMMC will continue bringing information on generic medicines closer to patients, employees, and the community—reinforcing the importance of access to quality medicines and the knowledge to use them safely and appropriately.\r\n𝐓𝐡𝐢𝐬 𝐢𝐬 𝐚 𝐝𝐞𝐯𝐞𝐥𝐨𝐩𝐢𝐧𝐠 𝐬𝐭𝐨𝐫𝐲.\r\nNeed assistance or have questions? You may contact the 𝐏𝐮𝐛𝐥𝐢𝐜 𝐀𝐬𝐬𝐢𝐬𝐭𝐚𝐧𝐜𝐞 𝐚𝐧𝐝 𝐂𝐨𝐦𝐩𝐥𝐚𝐢𝐧𝐭𝐬 𝐒𝐞𝐜𝐭𝐢𝐨𝐧 at 𝟎𝟗𝟔𝟏 𝟖𝟓𝟓 𝟗𝟐𝟎𝟕.\r\nFor patient referrals or help in coordinating care, you may contact the 𝐏𝐚𝐭𝐢𝐞𝐧𝐭 𝐍𝐚𝐯𝐢𝐠𝐚𝐭𝐢𝐨𝐧 𝐚𝐧𝐝 𝐑𝐞𝐟𝐞𝐫𝐫𝐚𝐥 𝐔𝐧𝐢𝐭 at 𝟎𝟗𝟓𝟏 𝟒𝟓𝟓 𝟒𝟏𝟓𝟒.', '[{\"url\": \"https://www.facebook.com/share/p/18HvfRbkoa/\", \"type\": \"Facebook\"}]', '10', '2026-09-22 09:44:23', '[{\"material\":\"Layout\",\"stored_name\":\"24d77f5f82c199eb536f7d559890503a.jpg\",\"original_name\":\"0 FRONT PAGE.jpg\",\"extension\":\"jpg\",\"drive_url\":\"\",\"size\":14605635,\"mime\":\"image/jpeg\",\"uploaded_by\":10,\"uploader_name\":\"ACE RAZ CABUGA\",\"uploaded_at\":\"2026-09-22 09:13:26\"},{\"material\":\"Layout\",\"stored_name\":\"7a6ad025ae4bac01ffe520de7d6d1faa.jpg\",\"original_name\":\"1.jpg\",\"extension\":\"jpg\",\"drive_url\":\"\",\"size\":9108229,\"mime\":\"image/jpeg\",\"uploaded_by\":10,\"uploader_name\":\"ACE RAZ CABUGA\",\"uploaded_at\":\"2026-09-22 09:44:15\"},{\"material\":\"Layout\",\"stored_name\":\"677de9ea8c53752628e0c22c58d202d8.jpg\",\"original_name\":\"2.jpg\",\"extension\":\"jpg\",\"size\":9059689,\"mime\":\"image/jpeg\",\"uploaded_by\":10,\"uploader_name\":\"ACE RAZ CABUGA\",\"uploaded_at\":\"2026-09-22 09:44:23\"},{\"material\":\"Layout\",\"stored_name\":\"efd378861efb1e47d567b7555c35df31.jpg\",\"original_name\":\"3.jpg\",\"extension\":\"jpg\",\"size\":9081521,\"mime\":\"image/jpeg\",\"uploaded_by\":10,\"uploader_name\":\"ACE RAZ CABUGA\",\"uploaded_at\":\"2026-09-22 09:44:23\"},{\"material\":\"Layout\",\"stored_name\":\"c78ebdfad08aa3d1ae7cb15830bb4544.jpg\",\"original_name\":\"4.jpg\",\"extension\":\"jpg\",\"size\":9306754,\"mime\":\"image/jpeg\",\"uploaded_by\":10,\"uploader_name\":\"ACE RAZ CABUGA\",\"uploaded_at\":\"2026-09-22 09:44:23\"},{\"material\":\"Layout\",\"stored_name\":\"5a4317d2629f7895e00501aac8063424.jpg\",\"original_name\":\"5.jpg\",\"extension\":\"jpg\",\"size\":9151737,\"mime\":\"image/jpeg\",\"uploaded_by\":10,\"uploader_name\":\"ACE RAZ CABUGA\",\"uploaded_at\":\"2026-09-22 09:44:23\"}]'),
('recognition', '8', '', '𝐀𝐒𝐓𝐌𝐌𝐂 𝐍𝐎𝐖 𝐇𝐀𝐒 𝐈𝐓𝐒 𝐅𝐈𝐑𝐒𝐓 𝐇𝐎𝐒𝐏𝐈𝐂𝐄 𝐀𝐍𝐃 𝐏𝐀𝐋𝐋𝐈𝐀𝐓𝐈𝐕𝐄 𝐌𝐄𝐃𝐈𝐂𝐈𝐍𝐄 𝐒𝐏𝐄𝐂𝐈𝐀𝐋𝐈𝐒𝐓 \r\nFor patients facing serious or life-limiting illness, good care is not only about treating disease. It is also about 𝐫𝐞𝐥𝐢𝐞𝐯𝐢𝐧𝐠 𝐩𝐚𝐢𝐧, 𝐩𝐫𝐨𝐯𝐢𝐝𝐢𝐧𝐠 𝐜𝐨𝐦𝐟𝐨𝐫𝐭, 𝐩𝐫𝐞𝐬𝐞𝐫𝐯𝐢𝐧𝐠 𝐝𝐢𝐠𝐧𝐢𝐭𝐲, 𝐚𝐧𝐝 𝐡𝐞𝐥𝐩𝐢𝐧𝐠 𝐩𝐚𝐭𝐢𝐞𝐧𝐭𝐬 𝐚𝐧𝐝 𝐟𝐚𝐦𝐢𝐥𝐢𝐞𝐬 𝐧𝐚𝐯𝐢𝐠𝐚𝐭𝐞 𝐝𝐢𝐟𝐟𝐢𝐜𝐮𝐥𝐭 𝐬𝐭𝐚𝐠𝐞𝐬 𝐨𝐟 𝐢𝐥𝐥𝐧𝐞𝐬𝐬.\r\nASTMMC strengthens this aspect of patient care with 𝐒𝐡𝐞𝐫𝐰𝐢𝐧 𝐀. 𝐂𝐚𝐛𝐚𝐥𝐥𝐞𝐫𝐨, 𝐌𝐃, 𝐃𝐅𝐌, 𝐅𝐏𝐒𝐇𝐏𝐌, Medical Specialist IV of Family and Community Medicine, successfully passing the 𝐒𝐮𝐛𝐬𝐩𝐞𝐜𝐢𝐚𝐥𝐭𝐲 𝐁𝐨𝐚𝐫𝐝 𝐄𝐱𝐚𝐦𝐢𝐧𝐚𝐭𝐢𝐨𝐧 𝐨𝐟 𝐭𝐡𝐞 𝐏𝐡𝐢𝐥𝐢𝐩𝐩𝐢𝐧𝐞 𝐒𝐨𝐜𝐢𝐞𝐭𝐲 𝐨𝐟 𝐇𝐨𝐬𝐩𝐢𝐜𝐞 𝐚𝐧𝐝 𝐏𝐚𝐥𝐥𝐢𝐚𝐭𝐢𝐯𝐞 𝐌𝐞𝐝𝐢𝐜𝐢𝐧𝐞, making him the Medical Center’s 𝐟𝐢𝐫𝐬𝐭 𝐇𝐨𝐬𝐩𝐢𝐜𝐞 𝐚𝐧𝐝 𝐏𝐚𝐥𝐥𝐢𝐚𝐭𝐢𝐯𝐞 𝐌𝐞𝐝𝐢𝐜𝐢𝐧𝐞 𝐒𝐩𝐞𝐜𝐢𝐚𝐥𝐢𝐬𝐭.\r\nHospice and palliative medicine focuses on improving the quality of life of people living with serious illness. It addresses pain and other distressing symptoms while considering the physical, emotional, social, and supportive needs of patients and their families.\r\nHaving this expertise at ASTMMC strengthens the care available to patients who may need it most—care that considers not only 𝐭𝐡𝐞 𝐢𝐥𝐥𝐧𝐞𝐬𝐬 𝐛𝐞𝐢𝐧𝐠 𝐭𝐫𝐞𝐚𝐭𝐞𝐝, 𝐛𝐮𝐭 𝐚𝐥𝐬𝐨 𝐭𝐡𝐞 𝐩𝐞𝐫𝐬𝐨𝐧 𝐥𝐢𝐯𝐢𝐧𝐠 𝐭𝐡𝐫𝐨𝐮𝐠𝐡 𝐢𝐭.\r\nFor patients and families, this milestone brings specialized expertise in 𝐜𝐨𝐦𝐟𝐨𝐫𝐭, 𝐝𝐢𝐠𝐧𝐢𝐭𝐲, 𝐪𝐮𝐚𝐥𝐢𝐭𝐲 𝐨𝐟 𝐥𝐢𝐟𝐞, 𝐚𝐧𝐝 𝐜𝐨𝐦𝐩𝐚𝐬𝐬𝐢𝐨𝐧𝐚𝐭𝐞 𝐬𝐮𝐩𝐩𝐨𝐫𝐭 𝐜𝐥𝐨𝐬𝐞𝐫 𝐭𝐨 𝐡𝐨𝐦𝐞.\r\nASTMMC congratulates 𝐃𝐫. 𝐂𝐚𝐛𝐚𝐥𝐥𝐞𝐫𝐨 on this professional milestone—an achievement that also represents a meaningful step forward in strengthening compassionate, patient-centered care for the communities we serve.\r\nNeed assistance or have questions? You may contact the 𝐏𝐮𝐛𝐥𝐢𝐜 𝐀𝐬𝐬𝐢𝐬𝐭𝐚𝐧𝐜𝐞 𝐚𝐧𝐝 𝐂𝐨𝐦𝐩𝐥𝐚𝐢𝐧𝐭𝐬 𝐒𝐞𝐜𝐭𝐢𝐨𝐧 at 𝟎𝟗𝟔𝟏 𝟖𝟓𝟓 𝟗𝟐𝟎𝟕.\r\nFor patient referrals or help in coordinating care, you may contact the 𝐏𝐚𝐭𝐢𝐞𝐧𝐭 𝐍𝐚𝐯𝐢𝐠𝐚𝐭𝐢𝐨𝐧 𝐚𝐧𝐝 𝐑𝐞𝐟𝐞𝐫𝐫𝐚𝐥 𝐔𝐧𝐢𝐭 at 𝟎𝟗𝟓𝟏 𝟒𝟓𝟓 𝟒𝟏𝟓𝟒.', '[{\"url\": \"https://www.facebook.com/share/p/1DmV2xUQwX/\", \"type\": \"Facebook\"}]', '13', '2026-09-22 09:32:46', '[{\"material\":\"Layout\",\"stored_name\":\"11bde7f15dab48861f89660b4db5924c.jpg\",\"original_name\":\"Congratulations famed.jpg\",\"extension\":\"jpg\",\"size\":8011345,\"mime\":\"image/jpeg\",\"uploaded_by\":13,\"uploader_name\":\"RECKLYN D. RUAZA, RN\",\"uploaded_at\":\"2026-09-21 16:36:13\"}]');
